import { Component, inject, signal, OnInit } from '@angular/core';
import { RouterOutlet, RouterLink, RouterLinkActive, Router, NavigationEnd } from '@angular/router';
import { NgIf } from '@angular/common';
import { filter } from 'rxjs';
import { XofPipe } from './shared/pipes/xof.pipe';
import { BalanceStore } from './core/store/balance.store';
import { ToastComponent } from './shared/components/toast.component';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [RouterOutlet, RouterLink, RouterLinkActive, NgIf, XofPipe, ToastComponent],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css'],
})
export class AppComponent implements OnInit {
  readonly balanceStore = inject(BalanceStore);
  private readonly router = inject(Router);

  readonly isLoggedIn = signal(!!localStorage.getItem('token'));
  readonly isAgent = signal(localStorage.getItem('role') === 'AGENT');

  ngOnInit(): void {
    this.router.events.pipe(filter(e => e instanceof NavigationEnd)).subscribe(() => {
      this.isLoggedIn.set(!!localStorage.getItem('token'));
      this.isAgent.set(localStorage.getItem('role') === 'AGENT');
    });
  }

  logout(): void {
    localStorage.clear();
    this.isLoggedIn.set(false);
    this.isAgent.set(false);
    this.router.navigate(['/login']);
  }
}

<ng-container *ngIf="isLoggedIn()">
  <nav class="navbar">
    <span class="brand">BadWallet</span>
    <div class="nav-links">
      <a routerLink="/dashboard" routerLinkActive="active">Dashboard</a>
      <a routerLink="/transactions" routerLinkActive="active">Transactions</a>
      <a routerLink="/transfer" routerLinkActive="active">Transfert</a>
      <a routerLink="/bills/current" routerLinkActive="active">Factures</a>
      <a *ngIf="isAgent()" routerLink="/admin/wallets" routerLinkActive="active">Admin</a>
    </div>
    <div class="navbar-right">
      <span class="balance">{{ balanceStore.balance() | xof }}</span>
      <button (click)="logout()" class="btn-logout">Deconnexion</button>
    </div>
  </nav>
</ng-container>
<main [class.container]="isLoggedIn()">
  <router-outlet></router-outlet>
</main>
<app-toast></app-toast>
